<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=app_require_auth();
$canView=app_has_permission('schedule.view',$user);$canManage=app_has_permission('schedule.manage',$user);$canSelf=app_has_permission('schedule.self',$user);$canStaffView=app_has_permission('staff.view',$user)||app_has_permission('staff.manage',$user);$canStaffManage=app_has_permission('staff.manage',$user);$canAgent=app_has_permission('schedule.agent',$user);
if(!$canView&&!$canManage&&!$canSelf&&!$canStaffView){http_response_code(403);exit('Scheduling permission required.');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Staff Scheduling</title><style>
