ze:24px;margin-top:5px}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.tab{border:1px solid var(--line);border-radius:999px;background:#fff;padding:8px 12px;font-size:10px;font-weight:900;cursor:pointer}.tab.active{background:var(--dark);border-color:var(--dark);color:#fff}.panel{display:none}.panel.active{display:block}.workspace{background:#fff;border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow);overflow:hidden}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:12px;border-bottom:1px solid var(--line);background:#faf9f6}.toolbar input,.toolbar select{border:1px solid var(--line);border-radius:9px;padding:8px;background:#fff}.schedule-grid{display:grid;grid-template-columns:repeat(7,minmax(150px,1fr));min-width:1080px}.schedule-wrap{overflow:auto}.day{min-height:520px;border-right:1px solid var(--line);background:#fcfcfa}.day:last-child{border-right:0}.day-head{position:sticky;top:0;background:#fff;border-bottom:1px solid var(--line);padding:10px;z-index:2}.day-head strong{display:block}.day-head small{color:var(--muted)}.day-body{padding:8px;display:grid;gap:7px;align-content:start}.shift{border:1px solid var(--line);border-left:4px solid var(--blue);border-radius:10px;padding:9px;background:#fff;cursor:pointer}.shift.open{border-left-color:var(--warn);background:#fffaf1}.shift.mine{box-shadow:inset 0 0 0 1px rgba(217,74,43,.18)}.shift strong{font-size:11px;display:block}.shift small{font-size:9px;color:var(--muted);display:block;margin-top:3px}.split{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(330px,.75fr)}.list{padding:10px;display:grid;gap:8px}.card{border:1px solid var(--line);border-radius:13px;padding:12px;background:#fff}.card h3{margin:0;font-size:13px}.card p{margin:5px 0 0;color:var(--muted);font-size:10px;line-height:1.5}.meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.pill{border-radius:999px;padding:4px 7px;font-size:8px;font-weight:900;text-transform:uppercase;background:#efefe9}.pill.good{background:#e6f3eb;color:var(--good)}.pill.warn{background:#fff1d8;color:var(--warn)}.pill.bad{background:#f9e8e5;color:var(--bad)}.detail{border-left:1px solid var(--line);padding:14px;min-height:540px}.detail h2{margin:0 0 5px;font-size:22px}.form{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.form label{font-size:9px;font-weight:800;color:var(--muted)}.form input,.form select,.form textarea{width:100%;border:1px solid var(--line);border-radius:9px;padding:8px;background:#fff;margin-top:4px}.form textarea{min-height:72px;resize:vertical}.wide{grid-column:1/-1}.footer-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.empty{padding:38px;text-align:center;color:var(--muted)}.availability-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:7px;padding:12px}.availability-day{border:1px solid var(--line);border-radius:12px;padding:9px}.availability-day h4{margin:0 0 8px;font-size:10px}.availability-day input{width:100%;border:1px solid var(--line);border-radius:8px;padding:7px;margin-bottom:6px}.coverage-table{width:100%;border-collapse:collapse}.coverage-table th,.coverage-table td{padding:9px;border-bottom:1px solid var(--line);font-size:10px;text-align:left}.coverage-table th{font-size:8px;text-transform:uppercase;color:var(--muted)}.agent-bar{position:fixed;left:50%;bottom:14px;transform:translateX(-50%);width:min(920px,calc(100% - 24px));z-index:80;background:#fff;border:1px solid #d9d9d2;border-radius:20px;box-shadow:0 18px 48px rgba(20,20,18,.18);padding:8px;display:flex;gap:7px}.agent-bar textarea{flex:1;border:0;outline:0;resize:none;min-height:42px;padding:11px}.agent-bar button{width:42px;border:0;border-radius:13px;background:var(--dark);color:#fff;cursor:pointer}.toast{position:fixed;right:18px;top:78px;background:var(--dark);color:#fff;padding:9px 12px;border-radius:10px;font-size:9px;z-index:100}.hidden{display:none}@media(max-width:1000px){.split{grid-template-columns:1fr}.detail{border-left:0;border-top:1px solid var(--line)}.kpis{grid-template-columns:repeat(3,1fr)}.availability-grid{grid-template-columns:1fr 1fr}.hero{align-items:start;flex-direction:column}}@media(max-width:620px){.shell{padding:14px}.kpis{grid-template-columns:1fr 1fr}.form{grid-template-columns:1fr}.wide{grid-column:auto}.availability-grid{grid-template-columns:1fr}.hero h1{font-size:31px}}
</style></head><body><header class="top"><div class="brand"><div class="logo">G</div><div><strong>Staff Scheduling</strong><small>People · Availability · Shifts · Coverage</small></div></div><div class="actions"><a class="btn" href="operations.php">Operations</a><a class="btn" href="index.php">Workspace</a><button class="btn accent" id="refresh">Refresh</button></div></header><main class="shell"><section class="hero"><div><p class="eyebrow">Restaurant Labor Operations</p><h1>Schedule people against the work.</h1><p>Manage employee profiles, recurring availability, time off, weekly shifts, swaps and staffing coverage while comparing scheduled labor with prep and operations workload.</p></div><div class="week-tools"><button class="btn" id="prevWeek">←</button><input id="weekPicker" type="date"><button class="btn" id="nextWeek">→</button><?php if($canManage):?><button class="btn dark" id="publishWeek">Publish</button><?php endif;?></div></section><section class="kpis"><article class="kpi"><small>Scheduled hours</small><strong id="scheduledHours">—</strong></article><article class="kpi"><small>Shifts</small><strong id="shiftCount">—</strong></article><article class="kpi"><small>Open shifts</small><strong id="openShifts">—</strong></article><article class="kpi"><small>Scheduled staff</small><strong id="scheduledStaff">—</strong></article><article class="kpi"><small>Coverage gaps</small><strong id="coverageGaps">—</strong></article><article class="kpi"><small>Open task hours</small><strong id="taskHours">—</strong></article></section><nav class="tabs"><button class="tab active" data-tab="schedule">Schedule</button><?php if($canStaffView||$canManage):?><button class="tab" data-tab="staff">Staff</button><?php endif;?><?php if($canSelf||$canManage):?><button class="tab" data-tab="availability">Availability</button><button class="tab" data-tab="requests">Requests</button><?php endif;?><?php if($canView):?><button class="tab" data-tab="coverage">Coverage + Workload</button><?php endif;?></nav><section class="panel active" data-panel="schedule"><div class="workspace split"><section class="schedule-wrap"><div class="toolbar"><input id="scheduleSearch" placeholder="Search employee, position, shift..."><?php if($canManage):?><button class="btn dark" id="newShift">Add shift</button><?php endif;?></div><div class="schedule-grid" id="scheduleGrid"></div></section><aside class="detail" id="shiftDetail"><div class="empty">Select a shift to view details<?php if($canManage):?> or add one<?php endif;?>.</div></aside></div></section><?php if($canStaffView||$canManage):?><section class="panel" data-panel="staff"><div class="workspace split"><section><div class="toolbar"><input id="staffSearch" placeholder="Search staff, title, position..."></div><div class="list" id="staffList"></div></section><aside class="detail" id="staffDetail"><div class="empty">Select a staff member to review the scheduling profile.</div></aside></div></section><?php endif;?><?php if($canSelf||$canManage):?><section class="panel" data-panel="availability"><div class="workspace"><div class="toolbar"><?php if($canManage):?><select id="availabilityUser"></select><?php endif;?><button class="btn dark" id="saveAvailability">Save availability</button><button class="btn" id="newTimeOff">Request time off</button></div><div class="availability-grid" id="availabilityGrid"></div><div class="list" id="exceptionList"></div></div></section><section class="panel" data-panel="requests"><div class="workspace"><div class="toolbar"><span style="font-size:10px;color:var(--muted)">Release and swap requests stay pending until manager approval.</span></div><div class="list" id="requestList"></div></div></section><?php endif;?><?php if($canView):?><section class="panel" data-panel="coverage"><div class="workspace"><div class="toolbar"><?php if($canManage):?><button class="btn dark" id="newCoverageRule">Add coverage rule</button><?php endif;?></div><div style="overflow:auto"><table class="coverage-table"><thead><tr><th>Date</th><th>Coverage</th><th>Time</th><th>Minimum</th><th>Scheduled</th><th>Gap</th></tr></thead><tbody id="coverageRows"></tbody></table></div><div class="list" id="workloadList"></div></div></section><?php endif;?></main><?php if($canAgent):?><div class="agent-bar"><textarea id="scheduleAgentInput" rows="1" placeholder="Hey Gelato… who works Friday? show coverage gaps… schedule Anthony Monday 4 to 10…"></textarea><button id="scheduleAgentSend">↑</button></div><?php endif;?><div id="toast" class="toast hidden"></div><script>window.SCHEDULING_CONFIG={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,userId:<?=(int)$user['id']?>,canView:<?=$canView?'true':'false'?>,canManage:<?=$canManage?'true':'false'?>,canSelf:<?=$canSelf?'true':'false'?>,canStaffView:<?=$canStaffView?'true':'false'?>,canStaffManage:<?=$canStaffManage?'true':'false'?>,canAgent:<?=$canAgent?'true':'false'?>};</script><script src="js/universal-admin-page-shell.js?v=20260915-3"></script><script src="js/scheduling.js?v=20260913-1"></script></body></html>